        left.push(-1);
        right.push(-1);
      }
    }
  }
  let best = 0;
  for (let root = 0; root < value.length; root++) {
    const walked = [];
    const stack = [];
    let at = root;
    while (at !== -1 || stack.length > 0) {
      while (at !== -1) {
        stack.push(at);
        at = left[at];
      }
      at = stack.pop();
      walked.push(value[at]);
      at = right[at];
    }
    let increasing = true;
    let sum = 0;
    for (let i = 0; i < walked.length; i++) {
