function groveHarvest(tree) {
  const value = [tree[0]];
  const left = [-1];
  const right = [-1];
  let index = 1;
  for (let node = 0; node < value.length && index < tree.length; node++) {
    if (index < tree.length) {
      const entry = tree[index++];
      if (entry !== null) {
        left[node] = value.length;
        value.push(entry);
        left.push(-1);
        right.push(-1);
      }
    }
    if (index < tree.length) {
      const entry = tree[index++];
      if (entry !== null) {
        right[node] = value.length;
        value.push(entry);
        left.push(-1);
        right.push(-1);
      }
    }
  }
  let best = 0;
  const visit = (node) => {
    if (node === -1) return { ordered: true, total: 0, low: Infinity, high: -Infinity };
    const l = visit(left[node]);
    const r = visit(right[node]);
    if (!l.ordered || !r.ordered || l.high >= value[node] || r.low <= value[node]) {
      return { ordered: false, total: 0, low: -Infinity, high: Infinity };
    }
    const total = l.total + r.total + value[node];
    if (total > best) best = total;
    return { ordered: true, total, low: Math.min(l.low, value[node]), high: Math.max(r.high, value[node]) };
  };
  visit(0);
  return best;
}
